//! The nine base texts of the study, and the numbers the prototype produced
//! for them.
//!
//! These are the Q4-Q12 base versions as they stood in the React prototype the
//! workbench replaces. They are here so the port can be held to the prototype's
//! arithmetic rather than merely resembling it: a readability figure recorded
//! during the study and one shown by this tool have to be the same number, or
//! the study's record and the tool's output cannot be compared at all.
//!
//! The expected metrics were generated by running the prototype's own
//! `analyze` and `countSyl` over these strings. They are an oracle, not a
//! judgement about what the right reading level is.

#![allow(dead_code)]

use workbench_core::hash::{Sha256Hex, Timestamp};
use workbench_core::protocol::{Question, Settings};
use workbench_core::rubric::{ChipId, Percent, Scores};

/// One base question: its number, its title, and the text the study used.
pub struct Base {
    pub ordinal: usize,
    pub title: &'static str,
    pub text: &'static str,
    /// The prototype's rubric chips: label and points.
    pub chips: &'static [(&'static str, i32)],
    /// What the prototype's `analyze` returned for `text`.
    pub words: usize,
    pub sentences: usize,
    pub grade: f64,
    pub ease: f64,
}

