/// Look one up by its number on the assignment.
pub fn base(ordinal: usize) -> &'static Base {
    BANK.iter().find(|b| b.ordinal == ordinal).expect("no such question in the bank")
}

// ------------------------------------------------------------------ helpers

/// A digest that is a digest, for tests that do not care which one.
pub fn digest(seed: &str) -> Sha256Hex {
    Sha256Hex::of(seed.as_bytes())
}

/// `2026-08-27T09:00:00Z` plus `minutes`, so a test can order its own events
/// without a clock.
pub fn at(minutes: u32) -> Timestamp {
    let h = 9 + minutes / 60;
    let m = minutes % 60;
    Timestamp::parse(&format!("2026-08-27T{:02}:{:02}:00Z", h, m)).expect("well-formed instant")
}

pub fn pct(v: f64) -> Percent {
    Percent::new(v).expect("a percentage")
}

/// A question built from the bank, with its prototype rubric loaded in.
pub fn question(ordinal: usize) -> Question {
    let b = base(ordinal);
    let mut q = Question::new(b.ordinal, b.title, b.text).expect("bank text is not empty");
    for (label, points) in b.chips {
        q.rubric_mut().add_chip(label, *points).expect("bank chip is valid");
    }
    q
}

/// A small question with two chips worth 2 and 8, so a grade lands on a round
/// number and a reader can check the arithmetic by eye.
pub fn simple() -> Question {
    let mut q = Question::new(1, "Simple", "Prove that two plus two is four.").unwrap();
    q.rubric_mut().add_chip("States the claim", 2).unwrap();
    q.rubric_mut().add_chip("Proves the claim", 8).unwrap();
    q
}

/// Mark every chip of a question's current rubric revision at `each`.
pub fn mark_all(q: &Question, each: f64) -> Scores {
    q.rubric()
        .current()
        .chips
        .iter()
        .map(|c| (c.id.clone(), pct(each)))
        .collect()
}

/// Mark named chips at one level and everything else at zero.
pub fn mark_only(q: &Question, full: &[&str], each: f64) -> Scores {
    q.rubric()
        .current()
        .chips
        .iter()
        .map(|c| {
            let v = if full.contains(&c.id.as_str()) { each } else { 0.0 };
            (c.id.clone(), pct(v))
        })
        .collect()
}

pub fn chip(q: &Question, n: usize) -> ChipId {
    q.rubric().current().chips[n].id.clone()
}

pub fn settings(threshold: f64) -> Settings {
    Settings { threshold: pct(threshold), ..Settings::default() }
}
